{
  "name": "工业相机",
  "name_en": "Industrial Camera",
  "manufacturer": "",
  "description": "工业相机是一类用于机器视觉和科研成像的电子成像设备，常用于实验中的图像采集、目标检测、尺寸测量和过程监控。此处证据显示设备支持通过底层寄存器端口进行打开、关闭、读写和访问模式查询，符合实验室中可编程视觉设备的典型控制方式。",
  "description_en": "An industrial camera is an electronic imaging device used for machine vision and scientific imaging. It is commonly used in laboratories for image acquisition, object detection, dimensional measurement, and process monitoring. The evidence here indicates low-level register-port access with open, close, read, write, and access-mode queries, which is typical of programmable vision devices used in lab setups.",
  "tag_hints": [
    "industrial camera",
    "machine vision",
    "image acquisition",
    "register access",
    "GenICam",
    "camera control port"
  ],
  "actions": [
    {
      "action_id": "auto-close",
      "action_name": "auto-close",
      "description": "关闭设备通信端口",
      "description_en": "Close the device communication port."
    },
    {
      "action_id": "auto-is_open",
      "action_name": "auto-is_open",
      "description": "查询设备通信端口是否已打开",
      "description_en": "Check whether the device communication port is open."
    },
    {
      "action_id": "auto-open",
      "action_name": "auto-open",
      "description": "打开设备通信端口",
      "description_en": "Open the device communication port."
    },
    {
      "action_id": "auto-read",
      "action_name": "auto-read",
      "description": "从指定地址读取设备寄存器数据",
      "description_en": "Read device register data from the specified address."
    },
    {
      "action_id": "auto-write",
      "action_name": "auto-write",
      "description": "向指定地址写入设备寄存器数据",
      "description_en": "Write device register data to the specified address."
    },
    {
      "action_id": "auto-port",
      "action_name": "auto-port",
      "description": "获取设备通信端口",
      "description_en": "Get the device communication port."
    },
    {
      "action_id": "auto-get_access_mode",
      "action_name": "auto-get_access_mode",
      "description": "获取访问模式",
      "description_en": "Get the access mode."
    }
  ]
}

